 "parameters": [
  {
   "name": "receiver_email",
   "type": "string",
   "required": true,
   "description": "Email address of the receiver.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "amount",
   "type": "number",
