   "name": "paid_amount",
   "type": "number",
   "required": true,
   "description": "The total amount of the expense paid.",
   "default": null,
   "constraints": []
  },
  {
   "name": "payer_email",
   "type": "string",
   "required": true,
   "description": "Email of the user who paid for the expense.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "debtor_emails",
   "type": "list[string]",
   "required": true,
   "description": "Emails of the users who owe a share of the expense.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from splitwise app login.",
   "default": null,
   "constraints": []
  },
